+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.*;
+
+/** UC-002: the live grid backed by PostgreSQL, including its lazy callbacks. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationDisplaysNamesAndAlphabeticallyOrderedSpecialtiesWithoutLogin() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected the veterinarian navigation link");
+        UI.getCurrent().navigate(link.getPath());
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        Grid<Vet> grid = grid();
+        assertEquals(6, test(grid).size());
+        assertEquals("First Name", test(grid).getHeaderCell(0));
+        assertEquals("Last Name", test(grid).getHeaderCell(1));
+        assertEquals("Specialties", test(grid).getHeaderCell(2));
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must not change the data");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void lazyCallbacksReturnBoundedNonOverlappingChunksUntilTheEnd() {
+        for (int index = 0; index < 125; index++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Vet", "Repeated").execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertEquals(131, test(grid).size());
+
+        List<Vet> loaded = new ArrayList<>();
+        for (int offset = 0; offset < 131; offset += 17) {
+            List<Vet> chunk = fetch(grid, offset, 17);
+            assertEquals(Math.min(17, 131 - offset), chunk.size());
+            loaded.addAll(chunk);
+        }
+        assertEquals(131, loaded.stream().map(Vet::id).distinct().count());
+        assertEquals(loaded, fetch(grid, 0, 131), "Page ordering must remain stable, including tied names");
+        assertTrue(fetch(grid, 131, 17).isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        Grid<Vet> grid = grid();
+        assertEquals(0, test(grid).size());
+        assertTrue(fetch(grid, 0, 50).isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsTheApplicationErrorViewWithoutTheGrid() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.dropTable(VETS).cascade().execute();
+
+        grid.getDataProvider().size(new Query<>());
+
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterFetchFailureReplacesTheLoadedGridWithTheApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertEquals(2, fetch(grid, 0, 2).size());
+        dsl.dropTable(VET_SPECIALTIES).execute();
+
+        assertTrue(fetch(grid, 2, 2).isEmpty());
+
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(H2.class).withText("Something happened...").single(),
+                "Expected the application error screen");
+        assertTrue(find(Grid.class).all().isEmpty(), "The failed veterinarian list must not remain visible");
+        assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Home").single(),
+                "Expected the navigation shell to remain usable");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected the veterinarians grid");
+    }
+
+    private List<Vet> fetch(Grid<Vet> grid, int offset, int limit) {
+        try (var rows = grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null))) {
+            return rows.toList();
+        }
+    }
+}
